(() => {
  window.__etnScrollZone = (from) => {
    let el = from.parentElement;
    while (el !== null && el !== document.body) {
      const overflowY = getComputedStyle(el).overflowY;
      if ((overflowY === 'auto' || overflowY === 'scroll') && el.scrollHeight > el.clientHeight + 2) {
        return el;
      }
      el = el.parentElement;
    }
    return null;
  };
  return true;
})()

