(() => {
  const bar = document.querySelector('.ui-comment .md-field-toolbar');
  if (bar === null) return null;
  const sc = window.__etnScrollZone(bar);
  return {
    position: getComputedStyle(bar).position,
    groups: document.querySelectorAll('.main-tab > .group').length,
    splitter: document.querySelectorAll('.main-tab > .row-splitter:not([hidden])').length,
    scroller: sc === null ? null : sc.className,
    scrollable: sc === null ? false : sc.scrollHeight > sc.clientHeight + 2,
  };
})()

